function cn(...classes: Array<string | false | undefined>) { return classes.filter(Boolean).join(' '); }

function Button({ children, className, variant = 'primary', ...props }: React.ButtonHTMLAttributes<HTMLButtonElement> & { variant?: 'primary' | 'ghost' | 'soft' }) {
  return <button className={cn('focus-ring inline-flex items-center justify-center gap-2 rounded-full px-4 py-2.5 text-sm font-semibold transition-all duration-300 disabled:cursor-not-allowed disabled:opacity-40', variant === 'primary' && 'bg-[#67e6f2] text-[#08101e] shadow-[0_10px_30px_rgba(103,230,242,.16)] hover:-translate-y-0.5 hover:bg-[#9af1f7]', variant === 'soft' && 'border border-[#7383ca]/25 bg-[#7685dd]/10 text-[#dbe1ff] hover:bg-[#7685dd]/20', variant === 'ghost' && 'text-[#a7b2d3] hover:bg-white/[.06] hover:text-white', className)} {...props}>{children}</button>;
}

function Glass({ children, className = '', ...props }: React.HTMLAttributes<HTMLDivElement>) {
  return <div className={cn('glass rounded-2xl', className)} {...props}>{children}</div>;
}

function Label({ children }: { children: ReactNode }) { return <div className="mono mb-2 text-[10px] uppercase tracking-[.22em] text-[#7f8bb0]">{children}</div>; }
function Pill({ children, color = '#67e6f2' }: { children: ReactNode; color?: string }) { return <span className="mono inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[10px] uppercase tracking-[.13em]" style={{ color, borderColor: `${color}40`, backgroundColor: `${color}0d` }}><CircleDot size={9} />{children}</span>; }

