type Cell = 'empty' | 'wall' | 'visited' | 'path' | 'start' | 'end';
const gridRows = 10, gridCols = 16;
const initialWalls = new Set([18,19,20,21,37,53,69,70,71,72,73,74,75,91,107,123,124,125,126,127]);

function Pathfinder() {
  const [algorithm, setAlgorithm] = useState('A*');
  const [cells, setCells] = useState<Cell[]>(() => Array.from({ length: gridRows * gridCols }, (_, i) => initialWalls.has(i) ? 'wall' : i === 9 ? 'start' : i === 150 ? 'end' : 'empty'));
  const [running, setRunning] = useState(false); const [visited, setVisited] = useState(0); const [pathLength, setPathLength] = useState(0); const [message, setMessage] = useState('Ready to trace a path.');
  const run = () => {
    if (running) return; setRunning(true); setMessage(`Tracing ${algorithm} frontier…`); setVisited(0); setPathLength(0);
    const start = 9, end = 150; const frontier = [start]; const seen = new Set([start]); const parent = new Map<number, number>(); const order: number[] = [];
    const h = (i: number) => Math.abs(Math.floor(i / gridCols) - Math.floor(end / gridCols)) + Math.abs(i % gridCols - end % gridCols);
    const score = (i: number) => algorithm === 'Greedy' ? h(i) : algorithm === 'A*' ? h(i) + (parent.has(i) ? 1 : 0) : algorithm === 'UCS' ? order.length : order.length;
    const timer = window.setInterval(() => {
      if (!frontier.length) { window.clearInterval(timer); setRunning(false); setMessage('No route found. Edit the walls and try again.'); return; }
      frontier.sort((a, b) => score(a) - score(b)); const current = algorithm === 'DFS' ? frontier.pop()! : frontier.shift()!; order.push(current);
      if (current === end) {
        window.clearInterval(timer); const path: number[] = []; let at = end; while (at !== start) { path.push(at); at = parent.get(at) ?? start; } path.push(start); path.reverse();
        setCells((prev) => prev.map((c, i) => path.includes(i) && c !== 'start' && c !== 'end' ? 'path' : c)); setPathLength(path.length - 1); setVisited(order.length); setRunning(false); setMessage(`Route found in ${order.length} explored states.`); return;
      }
      const neighbors = [current - gridCols, current + 1, current + gridCols, current - 1].filter((n) => n >= 0 && n < gridRows * gridCols && (Math.floor(n / gridCols) === Math.floor(current / gridCols) || n === current - gridCols || n === current + gridCols) && cells[n] !== 'wall' && !seen.has(n));
      neighbors.forEach((n) => { seen.add(n); parent.set(n, current); frontier.push(n); });
      setVisited(order.length); setCells((prev) => prev.map((c, i) => i !== start && i !== end ? (seen.has(i) ? 'visited' : c) : c));
    }, algorithm === 'DFS' ? 32 : 48);
  };
  const reset = () => { setCells(Array.from({ length: gridRows * gridCols }, (_, i) => initialWalls.has(i) ? 'wall' : i === 9 ? 'start' : i === 150 ? 'end' : 'empty')); setVisited(0); setPathLength(0); setMessage('Ready to trace a path.'); };
  const toggle = (i: number) => { if (running || i === 9 || i === 150) return; setCells((prev) => prev.map((c, idx) => idx === i ? c === 'wall' ? 'empty' : 'wall' : c)); };
  return <><PageIntro eyebrow="Pathfinder / search" title="Make the frontier visible." body="A destination is easy to name. The interesting part is everything an agent considers before it arrives. Draw a maze, choose a strategy, and watch the frontier negotiate it." action={<div className="flex flex-wrap gap-2">{['BFS','DFS','UCS','Greedy','A*'].map((a) => <button key={a} onClick={() => setAlgorithm(a)} className={cn('mono focus-ring rounded-full border px-3 py-2 text-[11px] transition', algorithm === a ? 'border-[#67e6f2]/50 bg-[#67e6f2]/10 text-[#67e6f2]' : 'border-white/10 text-[#7f8caf] hover:text-white')} data-testid={`button-algorithm-${a.toLowerCase().replace('*','star')}`}>{a}</button>)}</div>} /><section className="mx-auto grid max-w-[1440px] gap-5 px-5 pb-28 lg:grid-cols-[1fr_320px] lg:px-10"><Glass className="overflow-hidden p-4 sm:p-6"><div className="mb-5 flex items-center justify-between"><div><Label>Interactive grid / 16 × 10</Label><div className="flex items-center gap-2 text-sm text-[#aab5d2]"><span className="h-2 w-2 rounded-full bg-[#67e6f2]" />start <span className="ml-2 h-2 w-2 rounded-full bg-[#ff9bb7]" />goal</div></div><div className="flex gap-2"><Button variant="ghost" onClick={reset} aria-label="Reset pathfinder" data-testid="button-reset-pathfinder"><RotateCcw size={15} /> <span className="hidden sm:inline">Reset</span></Button><Button onClick={run} disabled={running} data-testid="button-run-pathfinder"><Play size={14} />{running ? 'Tracing' : 'Run search'}</Button></div></div><div className="grid-paper grid grid-cols-16 gap-1 rounded-xl border border-white/[.08] bg-[#080d1a] p-2" style={{ gridTemplateColumns: `repeat(${gridCols}, minmax(0, 1fr))` }} aria-label="Pathfinder editable grid">{cells.map((cell, i) => <button key={i} onClick={() => toggle(i)} aria-label={`Cell ${i + 1}, ${cell}`} className={cn('aspect-square rounded-[3px] border transition-colors duration-200', cell === 'wall' && 'border-[#53649b]/30 bg-[#33416d]', cell === 'visited' && 'border-[#4d99ad]/25 bg-[#20738a]/45', cell === 'path' && 'border-[#67e6f2]/60 bg-[#67e6f2]/80', cell === 'start' && 'border-[#67e6f2] bg-[#67e6f2] shadow-[0_0_12px_rgba(103,230,242,.5)]', cell === 'end' && 'border-[#ff9bb7] bg-[#ff9bb7] shadow-[0_0_12px_rgba(255,155,183,.35)]', cell === 'empty' && 'border-transparent hover:border-[#67e6f2]/30 hover:bg-[#67e6f2]/10')} data-testid={`cell-pathfinder-${i}`} />)}</div><p className="mono mt-4 text-[11px] text-[#7180a2]" data-testid="status-pathfinder">{message}</p></Glass><Glass className="h-fit p-5"><Label>Run telemetry</Label><div className="mt-5 grid grid-cols-2 gap-3"><Metric label="algorithm" value={algorithm} /><Metric label="explored" value={visited.toString().padStart(2,'0')} /><Metric label="path cost" value={pathLength ? `${pathLength} steps` : '—'} /><Metric label="heuristic" value={algorithm === 'A*' || algorithm === 'Greedy' ? 'Manhattan' : 'none'} /></div><div className="mt-6 border-t border-white/[.08] pt-5 text-sm leading-6 text-[#929dbc]"><span className="text-[#dbe2f8]">Tip:</span> click empty cells to sculpt obstacles. A* balances the cost already travelled with an estimate of the distance left.</div></Glass></section></>;
}

function Metric({ label, value }: { label: string; value: string }) { return <div className="rounded-xl border border-white/[.07] bg-white/[.025] p-3"><div className="mono text-[9px] uppercase tracking-[.15em] text-[#6f7b9e]">{label}</div><div className="mt-2 truncate font-['Space_Grotesk'] text-lg text-[#edf2ff]" data-testid={`metric-${label}`}>{value}</div></div>; }

type Mark = 'X' | 'O' | null;
function GameMind() {
  const [board, setBoard] = useState<Mark[]>(Array(9).fill(null)); const [thinking, setThinking] = useState(false); const [mode, setMode] = useState('Alpha–Beta'); const [nodes, setNodes] = useState(0); const [outcome, setOutcome] = useState('Your move · X');
  const winner = (b: Mark[]) => { const lines = [[0,1,2],[3,4,5],[6,7,8],[0,3,6],[1,4,7],[2,5,8],[0,4,8],[2,4,6]]; for (const [a,c,d] of lines) if (b[a] && b[a] === b[c] && b[a] === b[d]) return b[a]; return b.every(Boolean) ? 'draw' : null; };
  const scoreBoard = (b: Mark[], maximizing: boolean, alpha = -Infinity, beta = Infinity): number => { const result = winner(b); if (result === 'O') return 10; if (result === 'X') return -10; if (result === 'draw') return 0; let best = maximizing ? -Infinity : Infinity; b.forEach((v, i) => { if (!v) { const next = [...b]; next[i] = maximizing ? 'O' : 'X'; const value = scoreBoard(next, !maximizing, alpha, beta); nodesRef.current++; best = maximizing ? Math.max(best, value) : Math.min(best, value); if (mode === 'Alpha–Beta') { if (maximizing) alpha = Math.max(alpha, best); else beta = Math.min(beta, best); } } }); return best; };
  const nodesRef = { current: 0 };
  const move = (index: number) => { if (board[index] || thinking || winner(board)) return; const next = [...board]; next[index] = 'X'; setBoard(next); if (winner(next)) { setOutcome('You found the terminal state.'); return; } setThinking(true); setOutcome('Agent is evaluating…'); window.setTimeout(() => { nodesRef.current = 0; let best = -Infinity, bestIndex = next.findIndex((x) => !x); next.forEach((v, i) => { if (!v) { const candidate = [...next]; candidate[i] = 'O'; const value = scoreBoard(candidate, false); if (value > best) { best = value; bestIndex = i; } } }); const final = [...next]; final[bestIndex] = 'O'; setNodes(nodesRef.current); setBoard(final); setThinking(false); setOutcome(winner(final) === 'O' ? 'The agent found a line.' : winner(final) === 'draw' ? 'Board saturated · draw.' : 'Your move · X'); }, 550); };
  const reset = () => { setBoard(Array(9).fill(null)); setThinking(false); setNodes(0); setOutcome('Your move · X'); };
  return <><PageIntro eyebrow="Gamemind / adversarial search" title="Play against the decision tree." body="Tic-Tac-Toe is small enough to hold in your head and rich enough to show a machine choosing between futures. Challenge minimax, then turn on pruning to see how many branches disappear." /><section className="mx-auto grid max-w-[1440px] gap-5 px-5 pb-28 lg:grid-cols-[minmax(0,680px)_1fr] lg:px-10"><Glass className="p-5 sm:p-8"><div className="flex flex-wrap items-center justify-between gap-3"><div><Label>Human vs agent / 03 × 03</Label><div className="text-sm text-[#aeb8d4]" data-testid="status-gamemind">{outcome}</div></div><Button variant="ghost" onClick={reset} data-testid="button-reset-gamemind"><RotateCcw size={15} />New board</Button></div><div className="mx-auto mt-8 grid max-w-[430px] grid-cols-3 gap-2 rounded-2xl border border-white/[.08] bg-[#090e1c] p-2">{board.map((mark, i) => <button key={i} onClick={() => move(i)} aria-label={`Square ${i + 1} ${mark ?? 'empty'}`} className={cn("aspect-square rounded-xl border border-white/[.06] bg-white/[.02] font-['Space_Grotesk'] text-5xl transition hover:bg-white/[.06] sm:text-6xl", mark === 'X' ? 'text-[#67e6f2]' : 'text-[#b89bff]')} data-testid={`button-board-${i}`}>{mark}</button>)}</div></Glass><Glass className="h-fit p-5 sm:p-7"><div className="flex items-center justify-between"><Label>Thinking lens</Label><BrainCircuit size={19} className="text-[#b89bff]" /></div><div className="mt-3 flex rounded-xl border border-white/[.08] bg-black/10 p-1">{['Minimax','Alpha–Beta'].map((m) => <button key={m} onClick={() => setMode(m)} className={cn('focus-ring flex-1 rounded-lg px-3 py-2 text-xs transition', mode === m ? 'bg-[#b89bff]/15 text-[#d6c9ff]' : 'text-[#7d89aa]')} data-testid={`button-mode-${m.toLowerCase().replace('–','-')}`}>{m}</button>)}</div><div className="mt-5 grid grid-cols-2 gap-3"><Metric label="search mode" value={mode} /><Metric label="nodes scored" value={nodes.toString()} /></div><div className="mt-6 space-y-3 text-sm leading-6 text-[#929dbc]"><p className="flex gap-2"><span className="mt-2 h-1.5 w-1.5 shrink-0 rounded-full bg-[#b89bff]" />Minimax assumes the opponent will always choose the move that hurts it most.</p><p className="flex gap-2"><span className="mt-2 h-1.5 w-1.5 shrink-0 rounded-full bg-[#67e6f2]" />Alpha–Beta keeps the same answer while skipping branches that can no longer matter.</p></div></Glass></section></>;
}

function ConstraintX() {
  const [n, setN] = useState(8); const [queens, setQueens] = useState<number[]>([]); const [running, setRunning] = useState(false); const [steps, setSteps] = useState(0); const [status, setStatus] = useState('Ready for a clean board.');
  const run = () => { if (running) return; setRunning(true); setQueens([]); setSteps(0); setStatus('Backtracking through the constraint tree…'); const solution = solveQueens(n); let i = 0; const timer = window.setInterval(() => { if (i >= solution.length) { window.clearInterval(timer); setRunning(false); setStatus(`Solution found · ${solution.length} placements in the winning trace.`); return; } setQueens(solution[i]); setSteps(i + 1); i++; }, 280); };
  const clear = () => { setQueens([]); setSteps(0); setStatus('Ready for a clean board.'); };
  return <><PageIntro eyebrow="ConstraintX / constraint satisfaction" title="Every placement narrows tomorrow." body="N-Queens looks like a chess puzzle, but the lesson is about commitment. Place one queen per row; backtrack the moment a future collision becomes inevitable." /><section className="mx-auto grid max-w-[1440px] gap-5 px-5 pb-28 lg:grid-cols-[minmax(0,650px)_1fr] lg:px-10"><Glass className="p-5 sm:p-8"><div className="flex flex-wrap items-center justify-between gap-3"><div><Label>Backtracking board / {n} × {n}</Label><div className="text-sm text-[#aeb8d4]" data-testid="status-constraintx">{status}</div></div><div className="flex gap-2"><Button variant="ghost" onClick={clear} data-testid="button-clear-queens"><RotateCcw size={15} />Clear</Button><Button onClick={run} disabled={running} data-testid="button-run-queens"><Play size={14} />{running ? 'Solving' : 'Solve board'}</Button></div></div><div className="mx-auto mt-7 grid max-w-[480px] gap-0.5 rounded-xl border border-white/10 bg-[#090e1c] p-2" style={{ gridTemplateColumns: `repeat(${n}, minmax(0, 1fr))` }}>{Array.from({ length: n * n }, (_, i) => { const row = Math.floor(i / n), col = i % n; const queen = queens[row] === col; return <div key={i} className={cn('relative aspect-square flex items-center justify-center rounded-[2px]', (row + col) % 2 === 0 ? 'bg-[#182243]' : 'bg-[#101a34]')}>{queen && <div className="h-[58%] w-[58%] rounded-full border-2 border-[#85d8a4] bg-[#85d8a4]/20 shadow-[0_0_16px_rgba(133,216,164,.38)]" />}</div>; })}</div></Glass><Glass className="h-fit p-5 sm:p-7"><Label>Constraint controls</Label><div className="mt-4 flex items-center justify-between"><span className="text-sm text-[#aeb8d4]">Board size</span><span className="mono text-sm text-[#85d8a4]" data-testid="value-queen-size">{n} queens</span></div><input type="range" min="4" max="10" value={n} onChange={(e) => { setN(Number(e.target.value)); clear(); }} className="mt-4 w-full accent-[#85d8a4]" aria-label="N queens board size" data-testid="input-queen-size" /><div className="mt-7 grid grid-cols-2 gap-3"><Metric label="placed" value={`${queens.filter((q) => q >= 0).length}/${n}`} /><Metric label="steps" value={steps.toString()} /></div><div className="mt-6 border-t border-white/[.08] pt-5"><Label>What to notice</Label><p className="text-sm leading-6 text-[#929dbc]">The algorithm does not guess a complete answer. It makes the smallest safe commitment, then retreats only when a constraint is violated.</p></div></Glass></section><Timetable /></>;
}
function solveQueens(n: number) { const frames: number[][] = []; const board = Array(n).fill(-1); const safe = (r: number, c: number) => board.every((q, row) => q < 0 || (q !== c && Math.abs(q - c) !== Math.abs(row - r))); const visit = (r: number): boolean => { if (r === n) return true; for (let c = 0; c < n; c++) { if (safe(r, c)) { board[r] = c; frames.push([...board]); if (visit(r + 1)) return true; board[r] = -1; frames.push([...board]); } } return false; }; visit(0); return frames; }
function Timetable() { const [generated, setGenerated] = useState(false); const slots = [['09:00','Knowledge Representation','Dr. Rao'],['11:00','Intelligent Search','Prof. Iyer'],['14:00','Probabilistic Models','Dr. Sen'],['16:00','AI Lab / Open slot','Studio 2']]; return <section className="mx-auto max-w-[1440px] px-5 pb-28 lg:px-10"><Glass className="p-5 sm:p-7"><div className="flex flex-wrap items-center justify-between gap-4"><div><Label>Compact constraint demo</Label><h3 className="font-['Space_Grotesk'] text-xl text-[#eef2ff]">Timetable generator</h3><p className="mt-1 text-sm text-[#8491b3]">A tiny CSP: fit four sessions without a room or time collision.</p></div><Button variant="soft" onClick={() => setGenerated(true)} data-testid="button-generate-timetable"><Sparkles size={15} />{generated ? 'Regenerate' : 'Generate schedule'}</Button></div>{generated && <motion.div initial={{ opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} className="mt-6 grid gap-2 sm:grid-cols-2 lg:grid-cols-4">{slots.map(([time, title, owner], i) => <div key={time} className="rounded-xl border border-[#85d8a4]/20 bg-[#85d8a4]/[.05] p-4" data-testid={`card-timetable-${i}`}><div className="mono text-[10px] text-[#85d8a4]">{time}</div><div className="mt-2 text-sm font-semibold text-[#e7f3ec]">{title}</div><div className="mt-1 text-xs text-[#809b8e]">{owner}</div></div>)}</motion.div>}</Glass></section>; }

function LogicVault() {
  const [query, setQuery] = useState('can_fly'); const [mode, setMode] = useState('forward'); const [ran, setRan] = useState(true);
  const facts = ['bird(tweety)', 'animal(tweety)', 'feathers(tweety)']; const rules = ['bird(X) ∧ feathers(X) → can_fly(X)', 'can_fly(X) → moves(X)', 'animal(X) ∧ moves(X) → alive(X)']; const chain = query === 'can_fly' ? ['bird(tweety)', 'feathers(tweety)', 'can_fly(tweety)'] : query === 'alive' ? ['bird(tweety)', 'feathers(tweety)', 'can_fly(tweety)', 'moves(tweety)', 'animal(tweety)', 'alive(tweety)'] : ['No matching conclusion found'];
  return <><PageIntro eyebrow="LogicVault / symbolic reasoning" title="Follow the proof, not just the verdict." body="Facts sit still. Rules move. LogicVault lays the inference path between them so you can inspect exactly why a query is accepted—or where it stops." /><section className="mx-auto grid max-w-[1440px] gap-5 px-5 pb-28 lg:grid-cols-[.8fr_1.2fr] lg:px-10"><Glass className="p-5 sm:p-7"><div className="flex items-center justify-between"><Label>Knowledge base</Label><Database size={18} className="text-[#ffc777]" /></div><div className="mt-4"><div className="mono mb-2 text-[10px] text-[#697797]">FACTS / {facts.length}</div><div className="space-y-2">{facts.map((fact) => <div key={fact} className="rounded-lg border border-[#ffc777]/15 bg-[#ffc777]/[.04] px-3 py-2 font-mono text-xs text-[#e7d7b4]">{fact}</div>)}</div></div><div className="mt-6"><div className="mono mb-2 text-[10px] text-[#697797]">RULES / {rules.length}</div><div className="space-y-2">{rules.map((rule) => <div key={rule} className="rounded-lg border border-white/[.07] bg-white/[.025] px-3 py-2 font-mono text-xs leading-5 text-[#a7b2ce]">{rule}</div>)}</div></div></Glass><Glass className="p-5 sm:p-7"><div className="flex flex-wrap items-start justify-between gap-4"><div><Label>Query console</Label><h3 className="font-['Space_Grotesk'] text-2xl text-[#eef2ff]">Ask the vault.</h3></div><div className="flex rounded-lg border border-white/10 p-1">{['forward','backward'].map((m) => <button key={m} onClick={() => setMode(m)} className={cn('mono rounded-md px-3 py-1.5 text-[10px] uppercase', mode === m ? 'bg-[#ffc777]/15 text-[#ffc777]' : 'text-[#7582a3]')} data-testid={`button-chain-${m}`}>{m}</button>)}</div></div><div className="mt-6 flex gap-2"><input value={query} onChange={(e) => setQuery(e.target.value)} className="focus-ring min-w-0 flex-1 rounded-xl border border-white/10 bg-black/15 px-3 py-3 font-mono text-sm text-[#eef2ff] outline-none" aria-label="Logic query" data-testid="input-logic-query" /><Button onClick={() => setRan(true)} data-testid="button-run-query"><Search size={15} />Resolve</Button></div>{ran && <div className="mt-7"><div className="flex items-center justify-between"><Label>{mode} chain / reasoning path</Label><Pill color={chain[0] === 'No matching conclusion found' ? '#ff9bb7' : '#85d8a4'}>{chain[0] === 'No matching conclusion found' ? 'not entailed' : 'entailed'}</Pill></div><div className="mt-4 space-y-2">{chain.map((step, i) => <motion.div initial={{ opacity: 0, x: -8 }} animate={{ opacity: 1, x: 0 }} transition={{ delay: i * .08 }} key={`${step}-${i}`} className="flex items-center gap-3"><span className="mono flex h-6 w-6 shrink-0 items-center justify-center rounded-full border border-[#ffc777]/25 text-[10px] text-[#ffc777]">{String(i + 1).padStart(2,'0')}</span><div className={cn('flex-1 rounded-xl border px-3 py-2.5 font-mono text-xs', i === chain.length - 1 ? 'border-[#85d8a4]/30 bg-[#85d8a4]/[.06] text-[#bde7c9]' : 'border-white/[.07] bg-white/[.025] text-[#aab5d0]')}>{step}</div>{i < chain.length - 1 && <ChevronDown size={14} className="text-[#657292]" />}</motion.div>)}</div></div>}</Glass></section></>;
}

function PlanForge() {
  const [running, setRunning] = useState(false); const [done, setDone] = useState(3); const actions = [{ title: 'Pick up key', detail: 'at foyer', icon: Crosshair }, { title: 'Unlock archive', detail: 'with key', icon: ShieldCheck }, { title: 'Read blueprint', detail: 'in archive', icon: BookOpen }, { title: 'Return key', detail: 'to foyer', icon: Check }];
  const execute = () => { setRunning(true); setDone(0); let i = 0; const timer = window.setInterval(() => { i++; setDone(i); if (i === actions.length) { window.clearInterval(timer); setRunning(false); } }, 650); };
  return <><PageIntro eyebrow="PlanForge / state-space planning" title="A plan is a chain of reachable states." body="Planning is more than a to-do list. Each action changes the world. This miniature planner searches for a sequence where every precondition is true when the action arrives." /><section className="mx-auto max-w-[1440px] px-5 pb-28 lg:px-10"><Glass className="grid-paper p-5 sm:p-8"><div className="flex flex-wrap items-end justify-between gap-5"><div><Label>Goal state / archive_accessed = true</Label><h3 className="font-['Space_Grotesk'] text-2xl text-[#eef2ff]">Foyer → Archive</h3><p className="mt-2 text-sm text-[#8e9abb]">4 actions · 5 world states · 1 valid plan</p></div><Button onClick={execute} disabled={running} data-testid="button-execute-plan"><Play size={15} />{running ? 'Executing plan' : 'Run planner'}</Button></div><div className="relative mt-12"><div className="absolute left-8 right-8 top-8 hidden h-px bg-gradient-to-r from-[#67e6f2]/60 via-[#b89bff]/50 to-[#85d8a4]/60 sm:block" /><div className="grid gap-3 sm:grid-cols-4">{actions.map((action, i) => <motion.div key={action.title} animate={{ opacity: i < done ? 1 : .42, y: i < done ? 0 : 4 }} className="relative z-10 rounded-2xl border border-white/[.08] bg-[#10162b]/90 p-4" data-testid={`step-planforge-${i}`}><div className={cn('flex h-9 w-9 items-center justify-center rounded-xl border', i < done ? 'border-[#85d8a4]/35 bg-[#85d8a4]/10 text-[#85d8a4]' : 'border-white/10 bg-white/[.03] text-[#6e7b9d]')}>{i < done ? <Check size={16} /> : <action.icon size={16} />}</div><div className="mt-5 mono text-[10px] text-[#687596]">STEP 0{i + 1}</div><div className="mt-1 text-sm font-semibold text-[#e4e9fa]">{action.title}</div><div className="mt-1 text-xs text-[#7e8aaa]">{action.detail}</div></motion.div>)}</div></div><div className="mt-10 flex flex-wrap items-center gap-3 border-t border-white/[.08] pt-5 text-xs text-[#8490b1]"><span className="mono text-[10px] text-[#687596]">STATE TRACE</span><span className="rounded-full border border-white/10 px-3 py-1.5">key: foyer</span><ArrowRight size={13} /><span className="rounded-full border border-white/10 px-3 py-1.5">key: agent</span><ArrowRight size={13} /><span className="rounded-full border border-white/10 px-3 py-1.5">archive: open</span><ArrowRight size={13} /><span className="rounded-full border border-[#85d8a4]/25 bg-[#85d8a4]/[.05] px-3 py-1.5 text-[#a8dfb6]">goal: reached</span></div></Glass></section></>;
}

function Probabilix() {
  const [prior, setPrior] = useState(2); const [likelihood, setLikelihood] = useState(85); const [falsePositive, setFalsePositive] = useState(8); const posterior = (prior / 100 * likelihood / 100) / ((prior / 100 * likelihood / 100) + ((1 - prior / 100) * falsePositive / 100)) * 100;
  return <><PageIntro eyebrow="Probabilix / uncertainty" title="Belief is a moving number." body="Bayes' theorem turns a prior belief and new evidence into an updated belief. Move the sliders; the bars make the denominator impossible to ignore." /><section className="mx-auto grid max-w-[1440px] gap-5 px-5 pb-28 lg:grid-cols-[.8fr_1.2fr] lg:px-10"><Glass className="p-5 sm:p-7"><Label>Editable priors</Label><div className="mt-5 space-y-7"><ProbabilitySlider label="Prior probability" value={prior} setValue={setPrior} color="#a8b9ff" help="How common is the condition before evidence?" /><ProbabilitySlider label="Evidence sensitivity" value={likelihood} setValue={setLikelihood} color="#67e6f2" help="P(evidence | condition)" /><ProbabilitySlider label="False positive rate" value={falsePositive} setValue={setFalsePositive} color="#ff9bb7" help="P(evidence | no condition)" /></div></Glass><Glass className="p-5 sm:p-7"><div className="flex items-start justify-between"><div><Label>Posterior visualization</Label><h3 className="font-['Space_Grotesk'] text-2xl text-[#eef2ff]">What should we believe now?</h3></div><Activity className="text-[#67e6f2]" size={20} /></div><div className="mt-8 space-y-4"><ProbBar label="Condition + evidence" value={prior * likelihood / 100} color="#67e6f2" /><ProbBar label="No condition + evidence" value={(100-prior) * falsePositive / 100} color="#ff9bb7" /></div><div className="mt-8 rounded-2xl border border-[#a8b9ff]/25 bg-[#a8b9ff]/[.06] p-5"><div className="mono text-[10px] uppercase tracking-[.17em] text-[#8999d4]">Posterior probability</div><div className="mt-2 font-['Space_Grotesk'] text-6xl tracking-[-.06em] text-[#e7eafe]" data-testid="value-posterior">{posterior.toFixed(1)}<span className="text-3xl text-[#a8b9ff]">%</span></div><div className="mt-3 font-mono text-[11px] text-[#8995b7]">P(H|E) = P(E|H) · P(H) / P(E)</div></div></Glass></section></>;
}
function ProbabilitySlider({ label, value, setValue, color, help }: { label: string; value: number; setValue: (value: number) => void; color: string; help: string }) { return <div><div className="flex justify-between text-sm text-[#c4cce1]"><span>{label}</span><span className="mono" style={{ color }}>{value}%</span></div><input type="range" min="0" max="100" value={value} onChange={(e) => setValue(Number(e.target.value))} className="mt-3 w-full" style={{ accentColor: color }} aria-label={label} data-testid={`input-${label.toLowerCase().replaceAll(' ','-')}`} /><div className="mt-2 text-xs text-[#707d9f]">{help}</div></div>; }
function ProbBar({ label, value, color }: { label: string; value: number; color: string }) { return <div><div className="mb-2 flex justify-between text-xs text-[#8995b5]"><span>{label}</span><span className="mono" style={{ color }}>{value.toFixed(1)}%</span></div><div className="h-3 overflow-hidden rounded-full bg-white/[.06]"><motion.div animate={{ width: `${Math.max(value, 1)}%` }} className="h-full rounded-full" style={{ backgroundColor: color }} /></div></div>; }

function Lab() {
  const rows = [{ name: 'PATHFINDER', family: 'Search', state: 'frontier', observable: 'path cost', color: '#67e6f2' }, { name: 'GAMEMIND', family: 'Adversarial', state: 'game tree', observable: 'node count', color: '#b89bff' }, { name: 'CONSTRAINTX', family: 'CSP', state: 'partial board', observable: 'backtracks', color: '#85d8a4' }, { name: 'LOGICVAULT', family: 'Logic', state: 'knowledge base', observable: 'proof path', color: '#ffc777' }, { name: 'PLANFORGE', family: 'Planning', state: 'world state', observable: 'action depth', color: '#ff9bb7' }, { name: 'PROBABILIX', family: 'Uncertainty', state: 'belief', observable: 'posterior', color: '#a8b9ff' }];
  return <><PageIntro eyebrow="Lab / comparative lens" title="One atlas. Six signatures." body="Put the modules side by side. Their shared interface makes the difference in their internal worlds easier to spot." /><section className="mx-auto max-w-[1440px] px-5 pb-28 lg:px-10"><Glass className="overflow-hidden"><div className="overflow-x-auto"><table className="w-full min-w-[650px] text-left"><thead className="border-b border-white/[.08] bg-white/[.02]"><tr>{['Module','AI family','Working state','Visible signal','Open'].map((h) => <th key={h} className="mono px-5 py-4 text-[10px] font-normal uppercase tracking-[.17em] text-[#6f7c9d]">{h}</th>)}</tr></thead><tbody>{rows.map((row, i) => <tr key={row.name} className="border-b border-white/[.06] last:border-0 hover:bg-white/[.025]" data-testid={`row-lab-${i}`}><td className="px-5 py-5"><div className="flex items-center gap-3"><span className="h-2 w-2 rounded-full" style={{ backgroundColor: row.color }} /><span className="font-['Space_Grotesk'] text-sm font-semibold text-[#edf1ff]">{row.name}</span></div></td><td className="px-5 text-sm text-[#9ba7c5]">{row.family}</td><td className="px-5 font-mono text-xs text-[#8491b2]">{row.state}</td><td className="px-5 text-sm" style={{ color: row.color }}>{row.observable}</td><td className="px-5"><Link href={modules.find((m) => m.name === row.name)?.route ?? '/explore'} className="focus-ring inline-flex items-center gap-1 text-xs text-[#aab5d0] hover:text-white" data-testid={`link-lab-${row.name.toLowerCase()}`}>Inspect <ArrowRight size={13} /></Link></td></tr>)}</tbody></table></div></Glass><div className="mt-5 grid gap-5 md:grid-cols-3"><Glass className="p-5"><Timer size={18} className="text-[#67e6f2]" /><h3 className="mt-5 font-['Space_Grotesk'] text-lg text-[#edf1ff]">Step-by-step</h3><p className="mt-2 text-sm leading-6 text-[#8995b6]">Animations are paced for observation, not spectacle.</p></Glass><Glass className="p-5"><Code2 size={18} className="text-[#b89bff]" /><h3 className="mt-5 font-['Space_Grotesk'] text-lg text-[#edf1ff]">Readable states</h3><p className="mt-2 text-sm leading-6 text-[#8995b6]">The same small state objects power each visual trace.</p></Glass><Glass className="p-5"><ShieldCheck size={18} className="text-[#85d8a4]" /><h3 className="mt-5 font-['Space_Grotesk'] text-lg text-[#edf1ff]">No theatre</h3><p className="mt-2 text-sm leading-6 text-[#8995b6]">No model calls. No hidden service. Deterministic local algorithms only.</p></Glass></div></section></>;
}

function Learn() {
  const sections = [{ title: '01 · Intelligent agents', body: 'An agent observes a state, chooses an action, and changes the world. Search and planning differ mostly in how they represent the future.', module: 'PATHFINDER + PLANFORGE' }, { title: '02 · Adversarial search', body: 'Minimax models a rational opponent. Alpha–Beta pruning preserves the answer while refusing to evaluate branches that cannot influence it.', module: 'GAMEMIND' }, { title: '03 · Constraint satisfaction', body: 'A CSP is a set of variables, domains, and constraints. Backtracking is disciplined trial: make a safe assignment, then retreat from conflict.', module: 'CONSTRAINTX' }, { title: '04 · Knowledge & uncertainty', body: 'Logic systems derive what must be true. Bayesian systems update what is likely true. Both become clearer when the reasoning path is visible.', module: 'LOGICVAULT + PROBABILIX' }];
  return <><PageIntro eyebrow="Field notes / syllabus mapped" title="The short course behind the interface." body="A compact reading path for the ideas inside NetVerse AI. Read a note, then open the corresponding instrument while the concept is fresh." /><section className="mx-auto grid max-w-[1440px] gap-4 px-5 pb-28 lg:grid-cols-[1fr_340px] lg:px-10"><div className="space-y-4">{sections.map((section, i) => <Glass key={section.title} className="p-6 sm:p-8"><div className="flex gap-5"><span className="mono text-xs text-[#67e6f2]">0{i + 1}</span><div><h2 className="font-['Space_Grotesk'] text-2xl tracking-[-.03em] text-[#edf1ff]">{section.title}</h2><p className="mt-4 max-w-2xl text-sm leading-7 text-[#9ca8c8]">{section.body}</p><div className="mt-5 flex items-center gap-2 text-[10px] text-[#7683a5]"><BookOpen size={13} /> SYLLABUS THREAD <span className="text-[#c4cce0]">{section.module}</span></div></div></div></Glass>)}</div><Glass className="h-fit p-6"><Label>Suggested route</Label><div className="mt-5 space-y-1">{['Start with a maze','Meet the opponent','Respect constraints','Prove the claim','Forge the plan','Update your belief'].map((x, i) => <div key={x} className="flex items-center gap-3 border-b border-white/[.07] py-3 text-sm text-[#a6b1cf]"><span className="mono text-[10px] text-[#647192]">0{i + 1}</span>{x}<ChevronRight size={14} className="ml-auto text-[#5d6a8c]" /></div>)}</div><Link href="/explore" className="focus-ring mt-6 flex items-center justify-center gap-2 rounded-xl border border-[#67e6f2]/20 bg-[#67e6f2]/[.07] px-4 py-3 text-sm text-[#8debf2]" data-testid="link-learn-explore">Open the modules <ArrowRight size={14} /></Link></Glass></section></>;
}

function About() {
  const [members, setMembers] = useState(['Member 01','Member 02','Member 03']); const [editing, setEditing] = useState(false); const [draft, setDraft] = useState(members);
  const save = () => { setMembers(draft); setEditing(false); };
  return <><PageIntro eyebrow="About / project details" title="An instrument for seeing intelligence." body="NetVerse AI is a B.Tech CSE AI project built around a simple belief: classical algorithms deserve an interface as legible as their textbooks—and as alive as their execution." /><section className="mx-auto grid max-w-[1440px] gap-5 px-5 pb-28 lg:grid-cols-[1.15fr_.85fr] lg:px-10"><Glass className="grid-paper p-6 sm:p-8"><Label>Project brief</Label><div className="mt-5 grid gap-7 sm:grid-cols-2"><div><h2 className="font-['Space_Grotesk'] text-2xl text-[#eef2ff]">A credible demo, not a black box.</h2><p className="mt-4 text-sm leading-7 text-[#98a5c5]">Each scene is intentionally small: small enough to explain in a viva, expressive enough to reveal the mechanics of search, games, constraints, logic, planning, and probability.</p></div><div className="space-y-4 text-sm text-[#9aa6c6]"><div className="flex gap-3"><Check className="shrink-0 text-[#85d8a4]" size={17} />Deterministic local algorithms</div><div className="flex gap-3"><Check className="shrink-0 text-[#85d8a4]" size={17} />Explainable intermediate states</div><div className="flex gap-3"><Check className="shrink-0 text-[#85d8a4]" size={17} />Accessible, responsive interaction</div><div className="flex gap-3"><Check className="shrink-0 text-[#85d8a4]" size={17} />No external API or database</div></div></div><div className="mt-12 border-t border-white/[.08] pt-5"><div className="mono text-[10px] uppercase tracking-[.18em] text-[#647292]">Stack signature</div><div className="mt-3 flex flex-wrap gap-2">{['React','TypeScript','Framer Motion','Lucide','Classical AI'].map((x) => <span key={x} className="rounded-full border border-white/10 px-3 py-1.5 text-xs text-[#a7b2d0]">{x}</span>)}</div></div></Glass><Glass className="p-6 sm:p-8"><div className="flex items-start justify-between"><div><Label>Project constellation</Label><h2 className="font-['Space_Grotesk'] text-2xl text-[#eef2ff]">The team behind the trace.</h2></div><Github size={20} className="text-[#8491b4]" /></div><div className="mt-7 space-y-3">{members.map((member, i) => <div key={i} className="flex items-center gap-3 rounded-xl border border-white/[.08] bg-white/[.025] p-3"><span className="flex h-9 w-9 items-center justify-center rounded-full border border-[#67e6f2]/25 bg-[#67e6f2]/10 font-mono text-xs text-[#67e6f2]">0{i + 1}</span>{editing ? <input value={draft[i]} onChange={(e) => setDraft((old) => old.map((x,j) => j === i ? e.target.value : x))} className="focus-ring min-w-0 flex-1 rounded-lg border border-white/10 bg-black/15 px-2 py-2 text-sm text-white outline-none" aria-label={`Edit member ${i + 1}`} data-testid={`input-member-${i + 1}`} /> : <span className="text-sm text-[#ced5e9]" data-testid={`text-member-${i + 1}`}>{member}</span>}</div>)}</div><Button variant="soft" className="mt-5 w-full" onClick={() => editing ? save() : (setDraft(members), setEditing(true))} data-testid="button-edit-members">{editing ? <><Check size={15} />Save names</> : <><Code2 size={15} />Edit member placeholders</>}</Button></Glass></section></>;
}

function NotFound() { return <div className="mx-auto max-w-3xl px-5 py-32 text-center"><Pill>404 / signal lost</Pill><h1 className="mt-6 font-['Space_Grotesk'] text-5xl text-gradient">This route is unexplored.</h1><p className="mt-5 text-[#9da8c5]">The observatory could not resolve that coordinate.</p><Link href="/" className="focus-ring mt-8 inline-flex rounded-full bg-[#67e6f2] px-5 py-3 text-sm font-bold text-[#08101e]" data-testid="link-return-home">Return home</Link></div>; }

function Router() {
  return <Switch><Route path="/" component={Home} /><Route path="/explore" component={Explore} /><Route path="/pathfinder" component={Pathfinder} /><Route path="/gamemind" component={GameMind} /><Route path="/constraintx" component={ConstraintX} /><Route path="/logicvault" component={LogicVault} /><Route path="/planforge" component={PlanForge} /><Route path="/probabilix" component={Probabilix} /><Route path="/lab" component={Lab} /><Route path="/learn" component={Learn} /><Route path="/about" component={About} /><Route component={NotFound} /></Switch>;
}

function RoutedErrorBoundary({ children }: { children: ReactNode }) { const [location] = useLocation(); return <ErrorBoundary resetKey={location}>{children}</ErrorBoundary>; }
function App() { return <QueryClientProvider client={queryClient}><TooltipProvider><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, '')}><RoutedErrorBoundary><Shell><Router /></Shell></RoutedErrorBoundary></WouterRouter><Toaster /></TooltipProvider></QueryClientProvider>; }
export default App;